set -u
for sec in access effect result_relation authorization scope type parameter tensor pi_region pi_order pi_sharing; do
  printf '\n===== concise section %s =====\n' "$sec"
  out=$(python /input/tools/schema_query.py /input/schema/artifact.schema.json section "$sec" 2>&1) || { printf '%s\n' "$out" | tail -n 2; continue; }
  printf '%s\n' "$out" | python -c 'import json,sys; s=json.load(sys.stdin); print("required=",s.get("required")); print("properties=");
for k,v in s.get("properties",{}).items():
 print(" ",k, "enum="+repr(v.get("enum")) if isinstance(v,dict) and "enum" in v else "type="+repr(v.get("type")) if isinstance(v,dict) else repr(v), "pattern="+repr(v.get("pattern")) if isinstance(v,dict) and "pattern" in v else "")'
done
printf '\n===== operation object notes from queried contracts =====\n'
cat /work/query_needed.txt | sed -n '/===== op map_binary =====/,/===== section access =====/p'

